class TestClass {
    String getSomeString() {
        return "example";
    }

    void methodA(String paramString) {
        // Case 1: Local variable (matches)
        String localString = getSomeString();
        if (localString != null) {
            System.out.println("Local string is " + localString);
        }

        // Case 2: Parameter (matches)
        if (paramString != null) {
            System.out.println("Parameter string is " + paramString);
        }

        // Case 3: Method call result (matches)
        if (getSomeString() != null) {
            System.out.println("Method result is " + getSomeString());
        }
    }
}

afterExample:
class TestClass {
    String getSomeString() {
        return "example";
    }

    void methodA(String paramString) {
        // Case 1: Local variable (matches)
        String localString = getSomeString();
        if (localString != null && !localString.isEmpty()) {
            System.out.println("Local string is " + localString);
        }

        // Case 2: Parameter (matches)
        if (paramString != null && !paramString.isEmpty()) {
            System.out.println("Parameter string is " + paramString);
        }

        // Case 3: Method call result (matches)
        if (getSomeString() != null && !getSomeString().isEmpty()) {
            System.out.println("Method result is " + getSomeString());
        }
    }
}

negativeExample:
class NegativeTestClass {
    Object getSomeObject() {
        return new Object();
    }

    String getNullableString() {
        return null;
    }

    void methodB(Integer count) {
        // Negative Case 1: Non-String type
        Object obj = getSomeObject();
        if (obj != null) { // Should NOT match, $obj is not String
            System.out.println("Object is not null");
        }

        // Negative Case 2: Parameter of non-String type
        if (count != null) { // Should NOT match, $count is not String
            System.out.println("Count is not null");
        }

        // Negative Case 3: Different operator (== null)
        String nullableString = getNullableString();
        if (nullableString == null) { // Should NOT match, operator is ==
            System.out.println("Nullable string is null");
        }

        // Negative Case 4: No null check at all
        String anotherString = "test";
        if (anotherString.isEmpty()) { // Should NOT match, not a null check
            System.out.println("Another string is empty");
        }
    }
}
